  "d.109szp9": "Solida tereno aŭ strukturoj, kun kiuj eblas koliziiĝi.",
  "d.10azxrl": "Tri sunradiusoj super la fotosfero. Ombro estas vivo: la ŝirmilo de la platformo, la kometo, la grandaj karenoj. Ekbriloj venas ĉiujn kelkajn minutojn.",
  "d.10wlatv": "Propra koloro, kies plej hela kanalo estas sub 0x40, legiĝas kiel STOCK, do ŝirmilo neniam fariĝas nevidebla.",
  "d.11cuwtu": "RAKETOJ",
  "d.11jyj1n": "Destrojero konstruita ĉirkaŭ meza spina relpafilo, kun laserturelaj kaj dek ses raketaj ĉeloj.",
  "d.11phsqq": "Ludeldonisto, kiu permesas 100% AI-generitan enhavon, eldonas la ludon.",
  "d.11zjijr": "Armiloj povas esti elmetitaj kaj retiritaj (retiritaj armiloj estas kaŝitaj), kaj ŝipoj ne plu postlasas fumon.",
  "d.11zq7hg": "La aspekto: fizike lumigitaj pilotejoj, klasigitaj steloj, ringoza gasgiganto, fono de galaksio kaj nebulo, motoraj flamoj kaj navigaj lumoj; la ludsento de 0.1.0 fiksita.",
  "d.12zyt91": "ANVIL, la hangara bildo el la menuo de la ludo (kareno kiel konstruite por 0.3.0 kaj poste; denaska grandeco 256 x 128). Ekrankopio el la ludo, versio 0.6.1",
  "d.13cb0px": "Malamikoj super la urbo, kun motoraj flamoj (GLASGOW). Ekrankopio el la ludo, versio 0.5.3",
  "d.1436q76": "Versio 0.5.1 frostigita: armilsidejoj, rojoj de ses raketoj kaj ANVIL-hangaro, kiu lanĉas 10 NEEDLE.",
  "d.14s5uo6": "Motoraj flamoj sur kapitala ŝipo kaj batalŝipeto. Ekrankopio el la ludo, versio 0.5.3",
  "d.14vqvyw": "La ANVIL kun malfermita hangaro. Ekrankopio el la ludo, versio 0.6.1",
  "d.14zbb1f": "Malgranda batalŝipeto sub fajro de malamika flugilaro en la asteroida kampo THETA-7, ĝia ŝirmila veziko brilas.",
  "d.15oh132": "frostigitaj versioj",
  "d.16dme8w": "Fiksaj laseroj konverĝas al unu celpunkto antaŭ la ŝipo.",
  "d.16sui9e": "Flagŝipo grandas kiel urbo, kun rotacianta loĝtamburo, du pezaj spinaj reloj kaj arbaro da kanonoj.",
  "d.177y6xj": "Duobla akcelo.",
  "d.178olkv": "La destrojero ANVIL kun malfermita hangara pordo, el kiu elverŝiĝas lumo.",
  "d.17hv0ld": "Neniu gravito: libera falo.",
  "d.18fr12s": "KAPTŜIPETO",
  "d.18l8y3y": "Konstruita ĝis nun de unu fondinto.",
  "d.18qbnrf": "AI-generita antaŭfilmo estas produktita kune kun AI-generita artaĵo.",
  "d.18qvzf2": "NEEDLE, la hangara bildo el la menuo de la ludo (kareno kiel konstruite por 0.3.0 kaj poste; denaska grandeco 256 x 128). Ekrankopio el la ludo, versio 0.6.1",
